import axios from '../../api/axiosInstance';

// Categories — backend CategoryController (`/categories`, generated by make:module). REST; 422 = field errors.
// Category = { id, name, description, active, products_count (list only), created_at, updated_at }
// - getAll({ page, per_page, search, active, sort, order }) → { data: [Category], meta: { current_page, per_page, total } }   (category-list | product-list)
// - getById(id) → { data: Category }                    (category-list | category-edit)
// - create({ name, description, active }) → 201 { data } (category-create)
// - update(id, same) → { data }                          (category-edit)
// - remove(id) → { message }                             (category-delete; 422 while products use it)
const categoryApi = {
  getAll:  (params)      => axios.get('/categories', { params }),
  getById: (id)          => axios.get(`/categories/${id}`),
  create:  (payload)     => axios.post('/categories', payload),
  update:  (id, payload) => axios.put(`/categories/${id}`, payload),
  remove:  (id)          => axios.delete(`/categories/${id}`),
};

export default categoryApi;
